def equation(eps, T, params):
    p = params
    return (p[0] + p[1]*T + p[2]/T + p[3]*np.exp(-T)
            + (p[4] + p[5]/T)*eps**2 + p[6]/eps + p[7]*np.log(eps) + p[8]*eps + p[9]*T*eps)
